"use strict";

const fs = require("node:fs");
const path = require("node:path");
const policy = require("../trusted-shell-policy.js");

const root = path.join(__dirname, "..");
const output = `<!doctype html>
<!-- Generated by scripts/render-trusted-shell.js; do not hand-edit CSP. -->
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta
    http-equiv="Content-Security-Policy"
    content="${policy.outerPolicyContent()}"
  >
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>NMP Native Runtime trusted shell</title>
  <link rel="stylesheet" href="trusted-shell.css">
</head>
<body>
  <main id="surface" aria-label="Napplet surface">
    <div id="loading" role="status">Preparing verified napplet…</div>
  </main>
  <script src="trusted-shell-policy.js"></script>
  <script src="trusted-shell.js"></script>
</body>
</html>
`;

fs.writeFileSync(path.join(root, "trusted-shell.html"), output);
